import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet, useSheetToday } from '../session/session';
import { usePeople } from '../people/people';
import { useTerms } from '../settings/settings';

// Amounts travel as strings with two decimals ("13.50"); sums are added up in whole cents so no
// floating-point error shows.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when opened, the next on the sheet; null for a draft; a voided claim keeps it. */
  number: number | null;
  /** Fixed when settled (two decimals); null while live, or when no rate applied at settling. */
  settledDue: string | null;
  /** The user who opened it; null for a draft. */
  openedBy: string | null };
export type ClaimInput = { amount: string; date: string; note: string };

/** 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The active sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet ?? ''),
    queryFn: () => getJson<{ claims: Claim[] }>(`${base(sheet!)}/claims`).then((r) => r.claims),
    enabled: !!sheet,
  });
}

export const addClaim = (sheet: string, user: string, personId: number, input: ClaimInput) =>
  postJson<Claim>(`${base(sheet)}/people/${personId}/claims`, input, user);

/** The quick-add bar: a DRAFT claim dated the sheet's today with an empty note, for the named person
 *  (created with grade A when not on the sheet). */
export const quickAddClaim = (sheet: string, user: string, input: { name: string; amount: string }) =>
  postJson<Claim>(`${base(sheet)}/quick-claims`, input, user);

export const updateClaim = (sheet: string, user: string, id: number, input: ClaimInput) =>
  putJson<Claim>(`${base(sheet)}/claims/${id}`, input, user);

// A claim starts DRAFT; it can be opened, then settled; a DRAFT or OPEN claim can be voided.
// SETTLED and VOID are final. The server refuses a change not allowed; the screen refuses it first.
export type ClaimAction = 'open' | 'settle' | 'void';
export const CLAIM_ACTIONS: ClaimAction[] = ['open', 'settle', 'void'];
const ALLOWED: Record<ClaimAction, ClaimStatus[]> = { open: ['DRAFT'], settle: ['OPEN'], void: ['DRAFT', 'OPEN'] };
export const canTake = (claim: Claim, action: ClaimAction) => ALLOWED[action].includes(claim.status);

/** Only a DRAFT can be edited; to change an OPEN claim, void it and add a new one. */
export const canEdit = (claim: Claim) => claim.status === 'DRAFT';

/** Four eyes: the user who opened a claim cannot settle it. */
export const selfSettle = (claim: Claim, user: string, action: ClaimAction) =>
  action === 'settle' && claim.openedBy != null && claim.openedBy === user.trim();

export const claimAction = (sheet: string, user: string, id: number, action: ClaimAction) =>
  postJson<Claim>(`${base(sheet)}/claims/${id}/${action}`, {}, user);

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (claim: Claim) => claim.status === 'OPEN' || claim.status === 'SETTLED';

/** Whether a claim counts toward the live totals: as `counts`, except that the OPEN claims of a person
 *  on hold count in none (their SETTLED claims still do). */
export function useCounts() {
  const held = new Set((usePeople().data ?? []).filter((p) => p.held).map((p) => p.id));
  return (claim: Claim) => counts(claim) && !(claim.status === 'OPEN' && held.has(claim.personId));
}

const cents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
};

/** The amounts of the claims that count (by `counted`, from `useCounts`) added up, shown with two decimals. */
export function total(claims: Claim[], counted: (claim: Claim) => boolean): string {
  const sum = claims.filter(counted).reduce((n, c) => n + cents(c.amount), 0);
  return `${Math.floor(sum / 100)}.${String(sum % 100).padStart(2, '0')}`;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms in force (days). */
export function useDueBy() {
  const terms = useTerms();
  return (claim: Claim) => addDays(claim.date, terms);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function useOverdue() {
  const dueBy = useDueBy();
  const today = useSheetToday();
  return (claim: Claim) => claim.status === 'OPEN' && today !== undefined && dueBy(claim) < today;
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { hundredths } from '../rates/rates';

// A sheet's settings: the clerk limit (two decimals; null: no limit). And the role each user name has
// on the sheet: clerk (any name not given one) or steward. A clerk settles only a claim whose due is
// at or below the clerk limit; a steward settles any. The floor (two decimals, 1.00 until set): a
// claim's live due is at least it. The terms (whole days, 14 until set): a claim is due by its date plus them.
export type Settings = { clerkLimit: string | null; floor: string; terms: string };
export type Role = 'clerk' | 'steward';
export type UserRole = { user: string; role: Role };

/** Empty (unchanged), or a whole number of days, 0 or more. */
export const TERMS = /^(\d{1,4})?$/;

export const ROLES: Role[] = ['clerk', 'steward'];

/** Empty (no limit), or 0.00 or more with up to two decimals. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;
export const rolesKey = (sheet: string) => ['sheet', sheet, 'roles'] as const;

/** The active sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(`${base(sheet!)}/settings`),
    enabled: !!sheet,
  });
}

/** The roles assigned on the active sheet, by user name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesKey(sheet ?? ''),
    queryFn: () => getJson<{ roles: UserRole[] }>(`${base(sheet!)}/roles`).then((r) => r.roles),
    enabled: !!sheet,
  });
}

export const saveSettings = (sheet: string, user: string, settings: { clerkLimit: string; floor: string; terms: string }) =>
  postJson<Settings>(`${base(sheet)}/settings`, settings, user);

export const setRole = (sheet: string, user: string, input: { user: string; role: string }) =>
  postJson<UserRole>(`${base(sheet)}/roles`, input, user);

/** The floor in force before the sheet's settings load or any is set. */
export const DEFAULT_FLOOR = '1.00';

/** The active sheet's floor in cents: a claim's live due is at least it. */
export function useFloor(): bigint {
  return hundredths(useSettings().data?.floor ?? DEFAULT_FLOOR);
}

/** The terms in force before the sheet's settings load or any is set. */
export const DEFAULT_TERMS = '14';

/** The active sheet's terms in days: a claim is due by its date plus them. */
export function useTerms(): number {
  return Number(useSettings().data?.terms ?? DEFAULT_TERMS);
}

/** Whether the user may settle a claim with this due (cents; undefined for n/a, which is within any limit). */
export function useWithinClerkLimit() {
  const limit = useSettings().data?.clerkLimit ?? null;
  const roles = useRoles().data ?? [];
  return (user: string, due: bigint | undefined) => {
    const role = roles.find((r) => r.user === user.trim())?.role ?? 'clerk';
    return role === 'steward' || limit === null || due === undefined || due <= hundredths(limit);
  };
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { LIMIT, ROLES, TERMS, rolesKey, saveSettings, setRole, settingsKey, useRoles, useSettings } from './settings';

// The sheet's settings: the clerk limit (blank: no limit), the floor and the terms (blank: unchanged), each with
// the one in force shown beside it.
function SettingsPanel() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const settings = useSettings().data;
  const [limit, setLimit] = useState('');
  const [floor, setFloor] = useState('');
  const [terms, setTerms] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: { clerkLimit: string; floor: string; terms: string }) => saveSettings(sheet!, user, input),
    onSuccess: async (saved) => {
      queryClient.setQueryData(settingsKey(sheet!), saved);
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet!) });
    },
    onError: () => setError('The settings could not be saved: the clerk limit must be blank or 0.00 or more, and the floor blank or 0.00 or more, with up to two decimals, and the terms blank or a whole number of days.'),
  });

  if (!sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const value = limit.trim();
    if (!LIMIT.test(value)) {
      setError('The clerk limit must be blank or 0.00 or more, with up to two decimals.');
      return;
    }
    const floorValue = floor.trim();
    if (!LIMIT.test(floorValue)) {
      setError('The floor must be blank or 0.00 or more, with up to two decimals.');
      return;
    }
    const termsValue = terms.trim();
    if (!TERMS.test(termsValue)) {
      setError('The terms must be blank or a whole number of days, 0 or more.');
      return;
    }
    once(() => save.mutateAsync({ clerkLimit: value, floor: floorValue, terms: termsValue }));
  };

  return (
    <section data-testid="settings">
      <h2>Settings</h2>
      <form data-testid="settings-form" onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="No limit"
            inputMode="decimal"
            value={limit}
            onChange={(e) => {
              setLimit(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</strong>
        </span>{' '}
        <label>
          Floor{' '}
          <input
            data-testid="setting-floor"
            placeholder="Unchanged"
            inputMode="decimal"
            value={floor}
            onChange={(e) => {
              setFloor(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-floor-current">{settings?.floor ?? ''}</strong>
        </span>{' '}
        <label>
          Terms (days){' '}
          <input
            data-testid="setting-terms"
            placeholder="Unchanged"
            inputMode="numeric"
            value={terms}
            onChange={(e) => {
              setTerms(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <span>
          now <strong data-testid="setting-terms-current">{settings?.terms ?? ''}</strong>
        </span>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <span data-testid="settings-error">{error}</span>}
      </form>
    </section>
  );
}

// The roles on the sheet: a form that gives a user name a role (clerk or steward), replacing any it had,
// and each name given one. A name not listed is a clerk.
